package com.bytbeat.mpctrainer

/** Курс базовой работы с MPC. Названия аппаратных кнопок остаются как на реальном MPC. */
class LearnEngine(startLesson:Int=0){
 data class Snapshot(val loadedPads:Int=0,val eventCount:Int=0,val currentTrack:Int=0,val mutedTracks:Int=0,val tc:Int=16,val swing:Int=50,val noteRepeat:Boolean=false,val fullLevel:Boolean=false,val levels16:Boolean=false)
 data class Result(val advanced:Boolean,val lesson:Int,val message:String)
 var lesson:Int=startLesson.coerceIn(0,LAST_LESSON);private set
 private var baselineEvents=0;private var baselineTrack=0;private var baselineSwing=50;private var baselineTc=16;private var baselineMute=0;private var baselinePads=0
 private var challengeClean=false;private var challengeRecorded=false;private var challengeOverdub=false;private var challengeTc=false;private var challengeTrack=false;private var challengeStep=false;private var challengeMix=false;private var challengeSaved=false
 fun begin(s:Snapshot){baselineEvents=s.eventCount;baselineTrack=s.currentTrack;baselineSwing=s.swing;baselineTc=s.tc;baselineMute=s.mutedTracks;baselinePads=s.loadedPads;if(lesson==LAST_LESSON){resetChallenge();challengeClean=s.loadedPads==0&&s.eventCount==0}}
 private fun resetChallenge(){challengeClean=false;challengeRecorded=false;challengeOverdub=false;challengeTc=false;challengeTrack=false;challengeStep=false;challengeMix=false;challengeSaved=false}
 fun reset(s:Snapshot):Result{lesson=0;resetChallenge();begin(s);return Result(false,lesson,prompt())}
 fun report(action:String,s:Snapshot):Result{
  if(lesson==LAST_LESSON){
   if(action=="new_project"&&s.loadedPads==0&&s.eventCount==0){resetChallenge();challengeClean=true;baselineTrack=s.currentTrack;baselineTc=s.tc;baselinePads=0;baselineEvents=0}
   if(challengeClean){if(action=="stop")challengeRecorded=challengeRecorded||s.eventCount>0;if(action=="overdub_stop")challengeOverdub=challengeOverdub||s.eventCount>0;if(action=="tc"&&s.tc!=baselineTc)challengeTc=true;if(action=="track"&&s.currentTrack!=baselineTrack)challengeTrack=true;if(action=="step_added")challengeStep=true;if(action=="mixer_changed")challengeMix=true;if(action=="save")challengeSaved=true}
   val ok=challengeClean&&s.loadedPads>=2&&s.eventCount>=2&&challengeRecorded&&challengeOverdub&&challengeTc&&challengeTrack&&challengeStep&&challengeMix&&challengeSaved
   return Result(false,lesson,if(ok)"ОСНОВЫ ПРОЙДЕНЫ • Ты начал с чистого проекта, загрузил звуки, записал и дописал партии, изменил сетку, поработал с треками, Step Seq, выставил баланс громкости и сохранил проект." else challengeProgress(s))
  }
  val complete=when(lesson){0->action=="main";1->action=="loaded"&&s.loadedPads>baselinePads;2->action=="pad"&&s.loadedPads>0;3->action=="stop"&&s.eventCount>baselineEvents;4->action=="overdub_stop"&&s.eventCount>baselineEvents;5->action=="tc"&&s.tc!=baselineTc;6->action=="swing"&&s.swing!=baselineSwing;7->action=="note_repeat_pad"&&s.noteRepeat;8->action=="full_level_pad"&&s.fullLevel;9->action=="16_levels_pad"&&s.levels16;10->action=="step_added";11->action=="track"&&s.currentTrack!=baselineTrack;12->action=="track_mute"&&s.mutedTracks!=baselineMute;13->action=="chopped"&&s.loadedPads>0;14->action=="mixer_changed";else->false}
  return if(complete)advance(s)else Result(false,lesson,hint(action))
 }
 private fun advance(s:Snapshot):Result{if(lesson<LAST_LESSON)lesson++;begin(s);return Result(true,lesson,prompt())}
 fun title()=when(lesson){0->"1 • MAIN";1->"2 • BROWSE";2->"3 • Пэды";3->"4 • REC";4->"5 • OVERDUB";5->"6 • Timing Correct";6->"7 • Swing";7->"8 • Note Repeat";8->"9 • Full Level";9->"10 • 16 Levels";10->"11 • Step Sequencer";11->"12 • Треки";12->"13 • Track Mute";13->"14 • Sample Edit / Chop";14->"15 • Mixer / Volume";else->"Финальное задание"}
 fun explanation()=when(lesson){0->"MAIN возвращает на главный рабочий экран: здесь видны секвенция, трек, банк, темп и транспорт.";1->"BROWSE нужен для поиска и прослушивания звуков, а затем загрузки выбранного звука на пэд. Поддерживаются WAV и MP3.";2->"16 пэдов запускают назначенные звуки. Банки A–D дают четыре группы по 16 пэдов.";3->"REC начинает новую запись на текущем треке.";4->"OVERDUB дописывает новые удары поверх уже записанных событий, не стирая их.";5->"Timing Correct (TC) выравнивает удары по ритмической сетке, например 1/8, 1/16 или 1/32.";6->"Swing сдвигает часть долей сетки и меняет ощущение грува.";7->"NOTE REPEAT повторяет удерживаемый пэд с выбранным ритмическим делением.";8->"FULL LEVEL заставляет пэды играть с максимальной velocity. Экран телефона не чувствителен к силе нажатия.";9->"16 LEVELS раскладывает один выбранный звук на все 16 пэдов. В тренажёре доступны VELOCITY — громкость ударов и TUNE — высота звука. Запись TUNE пока недоступна.";10->"STEP SEQ позволяет программировать ритм по шагам. Здесь две тактовые страницы по 16 шагов.";11->"TRACK выбирает отдельную партию внутри текущей секвенции.";12->"TRACK MUTE временно заглушает трек, не удаляя записанные события.";13->"SAMPLE EDIT позволяет задать Start/End для WAV или MP3, нарезать сэмпл и разложить части по соседним пэдам.";14->"MIXER / VOLUME нужен для баланса: громкость выбранного пэда меняется отдельно, а MASTER / PROJECT управляет общей громкостью проекта, сохраняя соотношение между пэдами.";else->"Собери небольшой бит с чистого проекта без пошаговых подсказок. Тренажёр проверит реальные действия, а не результат предыдущих уроков."}
 fun prompt()=when(lesson){0->"ЗАДАНИЕ • Нажми MAIN.";1->"ЗАДАНИЕ • BROWSE → выбери звук → PREVIEW → LOAD TO PAD.";2->"ЗАДАНИЕ • Нажми пэд, на который уже загружен звук.";3->"ЗАДАНИЕ • REC → настучи короткий ритм → STOP.";4->"ЗАДАНИЕ • OVERDUB → добавь ещё один слой → STOP.";5->"ЗАДАНИЕ • Измени TC.";6->"ЗАДАНИЕ • Измени Swing.";7->"ЗАДАНИЕ • Включи NOTE REPEAT и удерживай пэд со звуком.";8->"ЗАДАНИЕ • Включи FULL LEVEL и нажми пэд со звуком.";9->"ЗАДАНИЕ • Выбери пэд со звуком, включи 16 LEVELS и сыграй одним из 16 уровней.";10->"ЗАДАНИЕ • Открой STEP SEQ и добавь один шаг.";11->"ЗАДАНИЕ • Переключись на другой TRACK.";12->"ЗАДАНИЕ • Включи или выключи TRACK MUTE.";13->"ЗАДАНИЕ • Выбери музыкальный сэмпл → SAMPLE EDIT → Start/End → CHOP TO PADS.";14->"ЗАДАНИЕ • MENU → MIXER / VOLUME → измени громкость выбранного пэда или MASTER → APPLY.";else->"ЭКЗАМЕН • Сначала NEW PROJECT. Без подсветки: загрузи 2+ звука → REC → OVERDUB → измени TC → другой TRACK → добавь шаг в Step Seq → выставь баланс в MIXER / VOLUME → SAVE."}
 fun lessonCard()="${title()}\n${explanation()}\n\n${prompt()}"
 private fun hint(action:String)=when(lesson){1->if(action=="browse")"Выбери звук, прослушай его через PREVIEW и нажми LOAD TO PAD."else prompt();3->if(action=="record")"Сыграй хотя бы один удар загруженным пэдом и нажми STOP."else prompt();4->if(action=="overdub")"Добавь хотя бы один новый удар и нажми STOP."else prompt();7->if(action=="note_repeat")"NOTE REPEAT включён. Удерживай пэд со звуком, чтобы тренажёр проверил реальное использование."else prompt();8->if(action=="full_level")"FULL LEVEL включён. Нажми пэд со звуком."else prompt();9->if(action=="16_levels")"16 LEVELS включён. Сыграй одним из пэдов уровней."else prompt();10->"Просто открыть STEP SEQ недостаточно — добавь шаг.";13->"Сделай нарезку CHOP, чтобы тренажёр увидел новые назначения на пэды.";14->"Недостаточно просто открыть MIXER / VOLUME — измени уровень и нажми APPLY.";else->prompt()}
 private fun challengeProgress(s:Snapshot):String{val checks=listOf("чистый проект" to challengeClean,"2+ звука" to (challengeClean&&s.loadedPads>=2),"REC" to challengeRecorded,"2+ события" to (challengeClean&&s.eventCount>=2),"OVERDUB" to challengeOverdub,"TC" to challengeTc,"другой TRACK" to challengeTrack,"Step Seq" to challengeStep,"баланс" to challengeMix,"SAVE" to challengeSaved);return "ЭКЗАМЕН • "+checks.joinToString("  •  "){(n,ok)->"${if(ok)"✓"else"○"} $n"}}
 companion object{const val LAST_LESSON=15}
}
